        int left   = x + f;

        int right  = x + w - f;

        int top    = y + f;

        int bottom = y + h + f;

        if (p_x > right) {

            x += p_x - right;

        } else if (p_x < left) {

            x -= left - p_x;

        }

        if (p_y > bottom) {

            y += p_y - bottom;

        } else if (p_y < top) {

            y -= top - p_y;

        }

    }



    c->x = FFMIN(FFMAX(0, x), geo->width  - w);

    c->y = FFMIN(FFMAX(0, y), geo->height - h);



    return 0;

}

